const OTHER='Other business or service';
function norm(v){return String(v??'').normalize('NFKC').toLowerCase().replace(/\s+/g,' ').trim();}
function words(v){return norm(v).normalize('NFD').replace(/\p{M}/gu,'').match(/[\p{L}\p{N}]+/gu)||[];}
function stem(w){return w.length>4&&w.endsWith('ies')?w.slice(0,-3)+'y':w.length>3&&w.endsWith('s')&&!w.endsWith('ss')&&!w.endsWith('us')?w.slice(0,-1):w;}
function phrase(text,value){return (' '+words(text).map(stem).join(' ')+' ').includes(' '+words(value).map(stem).join(' ')+' ');}
function businessMatch(text,c){if(c.business_type!==OTHER)return (categories[c.business_type]||[]).some(t=>phrase(text,t));const ignored=new Set(['and','or','the','business','businesses','company','companies','service','services']);const terms=words(c.niche).filter(w=>!ignored.has(w)).map(stem);const observed=new Set(words(text).map(stem));return terms.length>0&&terms.every(t=>observed.has(t));}
