const state=$('Prepare AI Research').first().json,c=state.config;
const packets=$('One Business Per AI Request').all();
const rows=[...state.errors];
if($input.all().length!==packets.length)throw Error('The number of model responses did not match the companies. No drafts were saved; inspect the Ollama node before retrying.');
for(const [i,item] of $input.all().entries()){
 const packet=packets[i]?.json;if(!packet)throw Error('The model response could not be matched to its company.');
 const b=packet.business,r=baseRow(c,b),first=packet.public_contacts[0];
 if(first){r.public_email=first.email;r.email_source_url=first.source_url;}
 try{
  if(item.json.error)throw Error('Ollama did not return a response. Check the local service and installed model.');
  if(item.json.done_reason==='length')throw Error('The local model exceeded its output budget. No draft was accepted.');
  const a=JSON.parse(item.json.message?.content||'');if(!['draft','skip'].includes(a.action))throw Error('The model did not return a valid decision.');
  const facts=[];for(const f of Array.isArray(a.evidence)?a.evidence.slice(0,8):[]){const p=b.pages[f.source_id-1],q=String(f.quote||'').trim();if(!p||!Number.isInteger(f.source_id)||!['service','area'].includes(f.kind)||q.length<8||q.length>600||!norm(text(p)).includes(norm(q)))continue;facts.push({kind:f.kind,quote:q,source_url:p.url});}
  r.business_name=String(a.company_name||r.business_name).slice(0,160);r.evidence_json=JSON.stringify(facts);r.opportunity=String(a.reason||a.opportunity||'').slice(0,1200);
  const match=businessMatch(facts.filter(f=>f.kind==='service').map(f=>f.quote).join(' '),c)&&areaMatch(facts.filter(f=>f.kind==='area').map(f=>f.quote).join(' '),c.location);
  if(a.action!=='draft'||!match){r.review_status='SKIPPED';r.error=match?'The model did not recommend drafting.':'Source quotes did not verify the selected business type and location.';rows.push(r);continue;}
  for(const [k,max]of [['subject',160],['email_draft',2000],['follow_up_draft',1200]])if(typeof a[k]!=='string'||!a[k].trim()||a[k].length>max)throw Error('The model returned incomplete or overly long draft content.');
  if(/^(re|fw|fwd):/i.test(a.subject)||/guarantee|\b\d+%|24\/7|our clients|our customers|we helped|free (implementation|setup|pilot)|\$\d/i.test(a.email_draft))throw Error('The draft contained an unsupported offer, result or subject.');
  const footer='\n\n'+c.sender_name+'\nAwtomateAI | '+c.business_website+'\n'+(c.postal_address||'[Add your business mailing address before using this message]')+"\n\nBusiness promotion from AwtomateAI. To stop these messages, reply 'no thanks'.";
  r.subject=a.subject.trim();r.introduction_draft=a.email_draft.trim()+footer;r.follow_up_draft=a.follow_up_draft.trim()+footer;
 }catch(e){r.review_status='RESEARCH_ERROR';r.error=String(e.message).slice(0,700);}
 rows.push(r);
}
return rows.map(json=>({json}));

